// Expected selections were generated with the original TypeScript serializer and ProseMirror schema.
use serde_json::Value;
use t3_client::thread_views::composer::editor::{
    BuildOptions, build_document, serialize_selection,
};

#[test]
fn every_selection_retains_the_typescript_shared_block_structure() {
    let cases: Value = serde_json::from_str(GOLDENS).expect("valid fixture");
    let mut failures = Vec::new();
    for case in cases.as_array().expect("valid fixture") {
        let source = case["text"].as_str().expect("valid fixture");
        let document = build_document(
            source,
            BuildOptions::default(),
            |name| Some((name.into(), None)),
            |_, _| false,
        );
        for range in case["ranges"].as_array().expect("valid fixture") {
            let from = range[0].as_u64().expect("valid fixture") as usize;
            let to = range[1].as_u64().expect("valid fixture") as usize;
            let actual = serialize_selection(&document, from, to);
            if actual.as_deref() != range[2].as_str() {
                failures.push(format!(
                    "{source:?} {from}..{to}: {actual:?} != {}",
                    range[2]
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches; first 30:\n{}",
        failures.len(),
        failures
            .iter()
            .take(30)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

